def can_form_word(tiles: str, word: str) -> bool:
    """
    Check if a given word can be formed using the given tiles.

    Args:
    tiles (str): A string representing the available tiles, each character in the string is a tile with a letter.
    word (str): A string representing the word to be formed.

    Returns:
    bool: Returns True if the word can be formed using the tiles, and False otherwise.
    """

    # Convert the tiles string into a dictionary for efficient lookups
    tile_dict = {}
    for tile in tiles:
        if tile in tile_dict:
            tile_dict[tile] += 1
        else:
            tile_dict[tile] = 1

    # Convert the word string into a dictionary for efficient lookups
    word_dict = {}
    for char in word:
        if char in word_dict:
            word_dict[char] += 1
        else:
            word_dict[char] = 1

    # Check if all letters in the word are present in the tiles
    for char in word:
        if char not in tile_dict or tile_dict[char] == 0:
            return False

    # Check if the number of occurrences of each letter in the word is less than or equal to 1
    for char in word:
        if word_dict[char] > 1:
            return False

    # If all checks pass, the word can be formed using the tiles
    return True

