def decode_string(s: str) -> str:
    """
    Decodes a given string that follows the pattern k[encoded_string], 
    where the encoded_string inside the square brackets is being repeated exactly k times.

    Args:
    s (str): The encoded string to be decoded.

    Returns:
    str: The decoded string.
    """
    stack = []
    num = 0
    temp = ""
    for char in s:
        if char.isdigit():
            num = num * 10 + int(char)
        elif char == '[':
            stack.append(temp)
            temp = ""
        elif char == ']':
            temp = temp + stack.pop()
        else:
            temp += char
    return temp + decode_string(temp)

def find_unique_element(arr):
    """
    Find the element that appears only once in an array where every element appears twice except for one.

    Args:
        arr (list): A list of integers where each integer appears exactly twice, except for one integer which appears only once.

    Returns:
        int: The integer that appears only once.
    """
    # Initialize a dictionary to store the frequency of each element
    freq_dict = {}

    # Iterate over the array to count the frequency of each element
    for num in arr:
        if num in freq_dict:
            freq_dict[num] += 1
        else:
            freq_dict[num] = 1

    # Iterate over the array again to find the element with a frequency of 1
    for num, freq in freq_dict.items():
        if freq == 1:
            return num

    # If no element with a frequency of 1 is found, return None
    return None

