def trap(height):
    if not height:
        return 0

    left, right = 0, len(height) - 1
    max_left, max_right = height[left], height[right]

    total_water = 0

    while left < right:
        # max_left < max_right
        if max_left < max_right:
            # 移动左边的指针
            left += 1
            # 如果当前高度大于 max_left，计算水的量
            if height[left] > max_left:
                total_water += max_left - height[left]
            # else break
            else:
                break
        # max_right < max_left
        else:
            # 移动右边的指针
            right -= 1
            # 如果当前高度大于 max_right，计算水的量
            if height[right] > max_right:
                total_water += max_right - height[right]
            # else break
            else:
                break

    return total_water

def groupBy(l, key):
    # Hash Table (Dictionary) approach
    ans = {}
    for elem in l:
        if key(elem) in ans:
            ans[key(elem)].append(elem)
        else:
            ans[key(elem)] = [elem]
    return ans

def groupBy2(l, key):
    # Hash Table (Dictionary) with custom key
    from collections import defaultdict
    ans = defaultdict(list)
    for elem in l:
        ans[key(elem)].append(elem)
    return dict(ans)

